function burst(x,y,color,n){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-190,190),vy:rand(-220,80),life:rand(.2,.8),color,kind:'spark'})}
function update(dt){time+=dt;if(!running||paused||!hero)return;hero.anim+=dt*(Math.abs(hero.vx)>.1?10:2);hero.attack=Math.max(0,hero.attack-dt);hero.attackCd=Math.max(0,hero.attackCd-dt);hero.roll=Math.max(0,hero.roll-dt);hero.rollCd=Math.max(0,hero.rollCd-dt);hero.invuln=Math.max(0,hero.invuln-dt);hero.skill=Math.max(0,hero.skill-dt);hero.mp=Math.min(hero.maxMp,hero.mp+dt*2.7);
let dir=(keys.a||keys.arrowleft||action.left?-1:0)+(keys.d||keys.arrowright||action.right?1:0);if(dir)hero.face=Math.sign(dir);if(hero.roll<=0){let speed=(keys.shift||action.run?320:220);if(hero.climb){hero.vy=(keys.w||keys.arrowup||action.climb?-205:0);if(keys.s||keys.arrowdown)hero.vy=160;hero.x+=dir*45*dt}else{hero.vx+=(dir*speed-hero.vx)*Math.min(1,dt*12);hero.vy+=1450*dt}}else hero.vy=0;
hero.x=clamp(hero.x+hero.vx*dt,0,worldW-hero.w);let oldBottom=hero.y+hero.h;hero.y+=hero.vy*dt;hero.onGround=false;for(let p of platforms){let horizontal=hero.x+hero.w>p.x&&hero.x<p.x+p.w;if(horizontal&&hero.vy>=0&&oldBottom<=p.y+4&&hero.y+hero.h>=p.y){hero.y=p.y-hero.h;hero.vy=0;hero.onGround=true;hero.climb=false}}if(hero.y>70){hero.y=-300;hero.hp-=15;toast('A hard landing');}
for(let e of enemies){if(e.dead)continue;e.phase+=dt;e.hit=Math.max(0,e.hit-dt);let dx=hero.x-e.x;if(Math.abs(dx)<340){e.x+=Math.sign(dx)*Math.min(Math.abs(dx),45*dt);if(Math.abs(dx)<56)e.attack+=dt;else e.attack=0;if(e.attack>1.1){e.attack=0;if(hero.invuln<=0){hero.hp-=e.type==='wisp'?9:8;hero.invuln=.6;burst(hero.x,hero.y+30,'#d66e58',7);tone(90,.18,'sawtooth',.04)}}}else e.x+=Math.sin(e.phase*1.1)*12*dt}
if(boss&&!boss.dead){boss.hit=Math.max(0,boss.hit-dt);let near=Math.abs(boss.x-hero.x)<720;if(near){boss.timer-=dt;if(boss.phase==='idle'&&boss.timer<=0){boss.phase='tell';boss.attackKind=(boss.turn++)%3;boss.timer=1.35;toast(['Briar lines bloom around you','A falling thorn column is marked','A ground-root surge approaches'][boss.attackKind])}else if(boss.phase==='tell'&&boss.timer<=0){boss.phase='strike';boss.timer=.42;let threatened=boss.attackKind===0?hero.x>boss.x-330&&hero.x<boss.x+35:boss.attackKind===1?Math.abs(hero.x-(boss.x-210))<95:hero.onGround;if(threatened&&hero.invuln<=0){hero.hp-=boss.attackKind===2?24:18;hero.invuln=.65;burst(hero.x+20,hero.y+45,'#e88d72',13);tone(65,.3,'sawtooth',.055)}}else if(boss.phase==='strike'&&boss.timer<=0){boss.phase='recover';boss.timer=.9}else if(boss.phase==='recover'&&boss.timer<=0){boss.phase='idle';boss.timer=1.45}}else{boss.phase='idle';boss.timer=Math.max(boss.timer,.8)}}
for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.kind==='spark'?200*dt:0;p.life-=dt}particles=particles.filter(p=>p.life>0);camera+=(clamp(hero.x-W*.36,0,worldW-W)-camera)*Math.min(1,dt*4);syncHud();if(hero.hp<=0){hero.hp=0;running=false;toast('You have fallen · begin again');setTimeout(()=>{if(!running){$('#intro').style.display='grid';$('.eyebrow').textContent='The path is never closed';$('.panel h1').innerHTML='Rise, wild one.'}},800)}}
function draw(){if(!hero)return;let st=stages[stageIndex],floorY=H*.78;ctx.clearRect(0,0,W,H);let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,st.sky[0]);sky.addColorStop(.63,st.sky[1]);sky.addColorStop(1,st.ground);ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// distant sun, ridges and atmospheric layers
let sx=W*.76-camera*.035;let sun=ctx.createRadialGradient(sx,H*.28,4,sx,H*.28,H*.36);sun.addColorStop(0,st.accent+'65');sun.addColorStop(1,st.accent+'00');ctx.fillStyle=sun;ctx.fillRect(0,0,W,H);
for(let layer=0;layer<3;layer++){let base=H*(.49+layer*.095),par=.06+layer*.10;ctx.beginPath();ctx.moveTo(0,H);for(let x=-70;x<W+100;x+=75){let wx=x+camera*par;let peak=base-Math.sin(wx*.003+layer*3)*52-Math.cos(wx*.008)*20;ctx.lineTo(x,peak)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#35494a99','#293d3dba','#253432e8'][layer];ctx.fill()}
// glimmering distance light and drifting haze
for(let i=0;i<5;i++){let x=(i*317-camera*.15+time*(4+i))%(W+350)-120;ctx.fillStyle=st.accent+'0c';ctx.beginPath();ctx.ellipse(x,H*(.52+i*.045),140,18,0,0,Math.PI*2);ctx.fill()}
// world ground slabs, roots and far trunks
ctx.save();ctx.translate(-camera,0);let gy=floorY;ctx.fillStyle=st.ground;ctx.fillRect(camera-30,gy,worldW+60,H-gy+10);ctx.fillStyle=st.accent+'45';ctx.fillRect(camera-30,gy,worldW+60,3);
for(let i=0;i<30;i++){let x=i*103+45;let y=gy;let h=randFixed(i,70,165);if(st.biome==='ash'){ctx.fillStyle='#2e2928';ctx.fillRect(x-9,y-h,20,h);ctx.fillStyle='#302a28';ctx.beginPath();ctx.arc(x,y-h,47,0,7);ctx.fill()}else if(st.biome==='coast'){ctx.fillStyle='#263a40';ctx.fillRect(x-8,y-h*.6,16,h*.6);ctx.fillStyle='#557d78';ctx.beginPath();ctx.ellipse(x,y-h*.6-18,45,24,.1,0,7);ctx.fill()}else{ctx.fillStyle='#263a33';ctx.fillRect(x-7,y-h,14,h);ctx.fillStyle='#29473b';ctx.beginPath();ctx.ellipse(x,y-h,45,27,0,0,7);ctx.fill();ctx.fillStyle='#4b6850';ctx.beginPath();ctx.ellipse(x-14,y-h-8,20,10,-.3,0,7);ctx.fill()}}
// glades and tall ornamental grass
for(let i=0;i<decor.length;i++){let d=decor[i],x=d.x,y=gy;if(x<camera-50||x>camera+W+60)continue;if(d.kind<.38){let sway=Math.sin(time*1.5+d.p)*7*d.s;ctx.strokeStyle=st.accent+'9a';ctx.lineWidth=1.4*d.s;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x+sway,y-22*d.s,x+sway*1.4,y-42*d.s);ctx.stroke();ctx.fillStyle=st.accent+'88';ctx.beginPath();ctx.ellipse(x+sway*1.4,y-42*d.s,5*d.s,2.2*d.s,-.5,0,7);ctx.fill()}else if(d.kind<.45){ctx.fillStyle=st.biome==='ash'?'#956d55':'#a7c783';ctx.beginPath();ctx.arc(x,y-3,3*d.s,0,7);ctx.fill()}}
for(let p of platforms.slice(1)){ctx.fillStyle='#172926';ctx.fillRect(p.x,p.y+floorY,p.w,20);ctx.fillStyle=st.accent+'99';ctx.fillRect(p.x,p.y+floorY,p.w,3);for(let k=0;k<6;k++){ctx.fillStyle='#172622';ctx.fillRect(p.x+randFixed(k+p.x,8,p.w-12),p.y+floorY+3,4,randFixed(k,6,13))}}
// distant wildlife: small deer silhouettes wander in the clearings
for(let i=0;i<6;i++){let x=(i*443+180+Math.sin(time*.23+i)*42);if(x<camera-80||x>camera+W+70)continue;let y=gy-8-Math.sin(time*2+i)*2;drawDeer(x,y,st.biome==='ash'?'#574d40':'#61785c',.66)}
for(let e of enemies)if(!e.dead)drawEnemy(e,gy,st);if(boss&&!boss.dead)drawBoss(gy,st);drawHero(gy,st);drawParticles(gy);
// front bank silhouettes
ctx.fillStyle='#101d1caa';ctx.beginPath();ctx.moveTo(camera-30,gy+28);for(let x=camera-30;x<camera+W+30;x+=48)ctx.lineTo(x,gy+25+Math.sin(x*.03+time)*8);ctx.lineTo(camera+W+40,H);ctx.lineTo(camera-30,H);ctx.fill();ctx.restore();
if(boss&&!boss.dead&&boss.phase==='tell')drawTelegraph(floorY,st);
// atmospheric motes in screen space
for(let i=0;i<34;i++){let x=(i*167+time*(8+i%4)*((i%2)?1:-1))%(W+30);let y=(i*97+Math.sin(time*.4+i)*35)%(H*.78);ctx.fillStyle=st.accent+(i%3===0?'57':'26');ctx.beginPath();ctx.arc(x,y,(i%3)+.4,0,7);ctx.fill()}
}
function randFixed(seed,a,b){let v=Math.sin(seed*127.1+311.7)*43758.5453;return a+(v-Math.floor(v))*(b-a)}
function drawDeer(x,y,color,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(0,-14,14,7,0,0,7);ctx.fill();ctx.fillRect(8,-25,4,15);ctx.beginPath();ctx.ellipse(12,-28,6,4,-.3,0,7);ctx.fill();for(let lx of [-8,7]){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(lx,-11);ctx.lineTo(lx+1,-1);ctx.stroke()}ctx.strokeStyle=color;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(13,-32);ctx.lineTo(15,-38);ctx.lineTo(18,-41);ctx.moveTo(13,-32);ctx.lineTo(11,-38);ctx.lineTo(8,-40);ctx.stroke();ctx.restore()}
function drawHero(gy,st){let sx=hero.x,sy=gy+hero.y,walking=Math.abs(hero.vx)>25,phase=hero.anim;ctx.save();ctx.translate(sx+hero.w/2,sy+hero.h/2);if(hero.face<0)ctx.scale(-1,1);if(hero.roll>0)ctx.rotate(Math.sin(time*38)*.7);let blink=hero.invuln>0&&Math.floor(time*22)%2===0;ctx.globalAlpha=blink?.42:1;
// cape flowing in a sculpted silhouette
ctx.fillStyle=classType==='Arcanist'?'#536f81':classType==='Ranger'?'#65764f':'#8c5445';ctx.beginPath();ctx.moveTo(-8,-20);ctx.quadraticCurveTo(-28,-7,-24+Math.sin(phase)*5,19);ctx.quadraticCurveTo(-9,23,0,15);ctx.lineTo(2,-16);ctx.fill();
// legs animate independently
for(let i=0;i<2;i++){let swing=walking?Math.sin(phase+i*Math.PI)*8:0;ctx.strokeStyle='#24282a';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-5+i*10,15);ctx.lineTo(-7+i*10+swing,29);ctx.lineTo(-5+i*10+swing,33);ctx.stroke();ctx.strokeStyle='#b5956f';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8+i*10+swing,32);ctx.lineTo(-1+i*10+swing,32);ctx.stroke()}
// torso and leather armor
ctx.fillStyle='#b49b77';ctx.beginPath();ctx.moveTo(-10,-19);ctx.lineTo(8,-19);ctx.lineTo(12,13);ctx.lineTo(-11,13);ctx.closePath();ctx.fill();ctx.fillStyle=classType==='Arcanist'?'#567282':classType==='Ranger'?'#556842':'#6e443b';ctx.beginPath();ctx.moveTo(-9,-17);ctx.lineTo(8,-17);ctx.lineTo(10,9);ctx.lineTo(-10,9);ctx.fill();ctx.strokeStyle='#d5bc8e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8,-8);ctx.lineTo(7,5);ctx.stroke();
// head, hood and hair
ctx.fillStyle='#c59d79';ctx.beginPath();ctx.arc(0,-25,9,0,7);ctx.fill();ctx.fillStyle=classType==='Arcanist'?'#384f60':'#392f2a';ctx.beginPath();ctx.arc(-1,-29,10,Math.PI,Math.PI*2);ctx.lineTo(8,-24);ctx.lineTo(-9,-24);ctx.fill();ctx.fillStyle='#f0d7a4';ctx.fillRect(4,-25,3,2);
// arm and drawn weapon arc
ctx.strokeStyle='#bd9a79';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(6,-11);ctx.lineTo(14,-4);ctx.stroke();if(hero.attack>0){ctx.strokeStyle=classType==='Arcanist'?'#8de6ed':classType==='Ranger'?'#dbcb9c':'#f2dfb6';ctx.lineWidth=4;ctx.shadowColor=ctx.strokeStyle;ctx.shadowBlur=14;ctx.beginPath();ctx.arc(12,-8,classType==='Warden'?34:23,-1.2,.9);ctx.stroke();ctx.shadowBlur=0}else if(classType==='Warden'){ctx.strokeStyle='#d9d4c3';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(13,-7);ctx.lineTo(26,-29);ctx.stroke();ctx.strokeStyle='#a4774d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(10,-10);ctx.lineTo(17,-6);ctx.stroke()}else if(classType==='Ranger'){ctx.strokeStyle='#b89460';ctx.lineWidth=2;ctx.beginPath();ctx.arc(17,-9,12,-1.2,1.2);ctx.stroke()}else{ctx.fillStyle='#9de8e3';ctx.shadowColor='#9de8e3';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(15,-13,5,0,7);ctx.fill();ctx.shadowBlur=0}ctx.restore()}

